"use client";
import {useState} from "react";
import {PricingSection} from "@/registry/rhs-ui/blocks/rhs-ui/pricing-section";
const plans=[{id:"personal",name:"Personal",description:"A little room for your ideas.",monthlyPrice:"€12",yearlyPrice:"€120",features:["One workspace","Unlimited projects","Community support"],action:"Choose Personal"},{id:"studio",name:"Studio",description:"A shared place to do your best work.",monthlyPrice:"€29",yearlyPrice:"€290",features:["Five workspaces","Unlimited projects","Team collaboration","Priority support"],featured:true,action:"Choose Studio"}];
export default function Demo():React.JSX.Element {const [selection,setSelection]=useState("");return <div className="mx-auto max-w-4xl p-6"><p className="text-center text-xs text-muted-foreground">Example pricing · This is not an RHS UI Pro offer</p><PricingSection plans={plans} onSelect={(id,interval)=>setSelection(`Selected ${id}, billed ${interval}. Demo only: no payment is taken.`)}/><p className="min-h-6 text-center text-sm" role="status">{selection}</p></div>;}
